(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x * 0.018 + t * 0.3) * 18 + Math.cos(y * 0.013 - t * 0.22) * 12;
  const w1y = Math.cos(y * 0.019 - t * 0.27) * 18 + Math.sin(x * 0.016 + t * 0.33) * 12;
  const w2x = Math.sin((x+y) * 0.01 + t * 0.15) * 8 + Math.cos((x-y) * 0.012 - t * 0.18) * 6;
  const w2y = Math.cos((x-y) * 0.011 - t * 0.2) * 8 + Math.sin((x+y) * 0.009 + t * 0.16) * 6;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*55, 0.11, 2.1],
    [400+Math.cos(t*0.38+2)*85, 200+Math.sin(t*0.58+4)*65, 0.065, 2.4],
    [200+Math.sin(t*0.52+1)*95, 220+Math.cos(t*0.42+3)*45, 0.095, 1.8]
  ];
  let aS = 0, iS = 0, cross = 0;
  for (let i = 0; i < src.length; i++) {
    const [sX, sY, f, sp] = src[i];
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const wa = Math.sin(d*f - t*sp), wi = Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    aS += wa; iS += wi;
    for (let j = i+1; j < src.length; j++) {
      const [sX2, sY2, f2, sp2] = src[j];
      const mx = (sX+sX2)*0.5, my = (sY+sY2)*0.5;
      const dm = Math.sqrt((sx-mx)**2 + (sy-my)**2);
      cross += Math.sin(dm*(f+f2)*0.3 - t*(sp+sp2)*0.4) * 0.15;
    }
  }
  const n = src.length;
  const act = aS/n, inh = iS/n, crs = cross/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
