  const pulse = Math.sin(dist*0.03 - t*1.8)*Math.exp(-dist*0.005)*0.3;
  const vortex = Math.sin(ang*5 + dist*0.02 - t*2.2)*Math.exp(-dist*0.008)*0.25;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(sx*0.3+t*1.5)*Math.sin(sy*0.35-t*1.2)*0.08;
  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + spiral + pulse + vortex + crs*0.5)*2.2);
  const blend = reaction*0.6 + cell*0.2 + micro*0.1 + crs*0.1;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[10,45,85],[18,90,115],[30,150,135],[80,180,120],
    [170,195,80],[220,175,60],[215,130,65],[185,80,75],[140,45,85],
    [85,25,70],[35,15,55],[5,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.75 + Math.sin(reaction*Math.PI)*0.25;
  const edge = Math.abs(reaction)>0.65 ? 1.0 + (Math.abs(reaction)-0.65)*0.6 : 0.92 + Math.abs(reaction)*0.12;
  const glow = Math.exp(-Math.abs(reaction)*3)*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*255)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*200)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*180)|0)
  ];
}
